def run(session, query, top_k):
    # The question is complex, covering deployment time, release schedule, support lifecycle,
    # and how these relate to new features like Virtual Agent Story Board and NLP Manager improvements.
    # The judge's diagnosis indicates aspect 6 (relation of release schedule to new features availability)
    # is missing and suggests optionally decomposing or using fusion retrieval (RRF) and authored OS DSL.
    #
    # Strategy:
    # 1) Use a hybrid search on the full query to get a broad relevant set.
    # 2) Use a fielded query with boosts on title and text to catch exact matches on key terms.
    # 3) Use a crafted OpenSearch DSL query to specifically target documents mentioning:
    #    - release schedule
    #    - support lifecycle
    #    - Virtual Agent Story Board
    #    - NLP Manager improvements
    #
    # Then fuse the results with fuse_ids and rerank to get the best top_k answers.

    # Hybrid search on full query
    ids_hybrid = session.search(query, top_k=top_k*3, mode='hybrid').ids()

    # Fielded query with boosts on title and text (if supported)
    if hasattr(session.store, 'query_fielded'):
        ids_fielded = session.store.query_fielded(query, ['title^2', 'text'], top_k=top_k*3)
    else:
        ids_fielded = []

    # Crafted OpenSearch DSL query to target key aspects:
    # We want documents that mention release schedule or support lifecycle AND
    # mention Virtual Agent Story Board or NLP Manager improvements.
    # Use bool must + should + match_phrase for precision.
    body = {
        "size": top_k*3,
        "query": {
            "bool": {
                "must": [
                    {
                        "bool": {
                            "should": [
                                {"match_phrase": {"text": "release schedule"}},
                                {"match_phrase": {"text": "support lifecycle"}},
                                {"match_phrase": {"title": "release schedule"}},
                                {"match_phrase": {"title": "support lifecycle"}}
                            ],
                            "minimum_should_match": 1
                        }
                    },
                    {
                        "bool": {
                            "should": [
                                {"match_phrase": {"text": "Virtual Agent Story Board"}},
                                {"match_phrase": {"text": "NLP Manager improvements"}},
                                {"match_phrase": {"title": "Virtual Agent Story Board"}},
                                {"match_phrase": {"title": "NLP Manager improvements"}}
                            ],
                            "minimum_should_match": 1
                        }
                    }
                ]
            }
        }
    }
    ids_dsl = [h['_id'] for h in session.store._search(body)['hits']['hits']]

    # Fuse all retrieved ids with Reciprocal Rank Fusion
    fused_ids = fuse_ids([ids_hybrid, ids_fielded, ids_dsl])

    # Rerank top_k from fused results
    reranked_ids = rerank(session, query, fused_ids, top_k=top_k)

    return reranked_ids
